preConditionHook:
// CountIF counts bars 0..N-1 INCLUDING the current bar and the counted
// condition is a true series (EL_FEATURES `countif`, VERIFIED). The counted
// condition is on PRICES, which have real history back to the chart start,
// so no zero-filled variable mirror is needed. The counts are EL numeric
// variables, kept as doubles; every comparison is an EL relational.
downBars = 0.0;
upBars = 0.0;
twoDown = false;
twoUp = false;
for (int i = 0; i < (int)spikeBars; ++i) {
    if (el_lt(close[i], open[i])) downBars += 1;
    if (el_gt(close[i], open[i])) upBars += 1;
}
for (int i = 0; i <= (int)spikeBars - 2; ++i) {
    if (el_lt(close[i], open[i]) && el_lt(close[i + 1], open[i + 1])) twoDown = true;
    if (el_gt(close[i], open[i]) && el_gt(close[i + 1], open[i + 1])) twoUp = true;
}
